<script setup>
import {computed,onMounted} from 'vue';import {useI18n} from 'vue-i18n';import {fleetStore} from '../../application/fleet.store.js';import AssetItem from './asset-item.vue';const {t}=useI18n();const assets=computed(()=>fleetStore.assets.value);const state=fleetStore.state;const emit=defineEmits(['select']);function selectAsset(asset){fleetStore.selectAsset(asset);emit('select',asset);}onMounted(()=>fleetStore.loadAssets());
</script>
<template><section><div class="flex justify-content-between mb-4"><div><h1 class="m-0">{{t('fleet.assetsTitle')}}</h1><p class="text-600">{{t('fleet.assetsSubtitle')}}</p></div><pv-button icon="pi pi-refresh" text rounded @click="fleetStore.loadAssets"/></div><pv-message v-if="state.errorMessage" severity="error" :closable="false">{{state.errorMessage}}</pv-message><div v-if="state.isLoading" class="grid"><div v-for="n in 6" :key="n" class="col-12 md:col-6 lg:col-4"><pv-skeleton height="10rem"/></div></div><div v-else-if="assets.length" class="grid"><div v-for="asset in assets" :key="asset.id" class="col-12 md:col-6 lg:col-4"><asset-item :asset="asset" @select="selectAsset"/></div></div><pv-message v-else severity="info" :closable="false">{{t('fleet.noAssets')}}</pv-message></section></template>
